SELECT FROM tianquan_oauth.oauth_consent WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id ASC

mapper.update:
UPDATE tianquan_oauth.oauth_consent
SET authorities = #{po.authorities, typeHandler=top.egon.cola.platform.tianquan.shoubing.admin.oauth.dao.OAuthStringListJsonbTypeHandler},
    granted_at = #{po.grantedAt}, status = #{po.status}, version = #{po.version},
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND client_pk = #{po.clientPk}
  AND subject = #{po.subject} AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_consent
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
